insert into public.driver_plans (code, name, monthly_price, commission_per_20) values ('basic', 'Basic', 0, 5), ('premium', 'Premium', 200, 2) on conflict (code) do update set name = excluded.name, monthly_price = excluded.monthly_price, commission_per_20 = excluded.commission_per_20;
insert into public.achievements (code, name, description, required_rides, icon_name) values ('first_ride', 'First Ride', 'Complete your first PasaBai ride.', 1, 'flag'), ('five_rides', 'Five Rides Completed', 'Complete five rides.', 5, 'route'), ('ten_rides', 'Ten Rides Completed', 'Complete ten rides.', 10, 'trophy'), ('consistent_commuter', 'Consistent Commuter', 'Complete twenty rides.', 20, 'sparkles'), ('reliable_driver', 'Reliable Driver', 'Complete fifty rides.', 50, 'shield-check') on conflict (code) do nothing;
